<script setup lang="ts">import {computed} from 'vue';import type {ElderApp} from '../../composables/useElderApp';const p=defineProps<{app:ElderApp}>();const message=computed(()=>p.app.state.data?.messages.find(x=>x.id===p.app.state.selected));</script>
<template><div class="content"><section v-if="message" class="card"><h2>{{ message.title }}</h2><p class="muted">{{ message.time }}</p><p>{{ message.text }}</p><p>{{ message.detail }}</p><button v-if="message.type==='sos'" class="primary" @click="app.go('requests')">查看演示求助记录</button></section><p v-else class="empty">消息详情尚未接入</p></div></template>
